function estimate(weightKg, activityMin, climate){
  if(!(weightKg>0)) return null;
  var base=weightKg*0.033;
  var act=(activityMin>0?activityMin:0)*0.005; // 每运动分钟 +0.005 L
  var cli=(climate==='hot')?0.5:(climate==='dry'?0.3:0);
  return Math.round((base+act+cli)*100)/100;
}
var EXPORTS={estimate:estimate};


